mapper.select:
SELECT * FROM Inquiry 
    WHERE id = #{id}
    ORDER BY i_idx DESC;

mapper.update:
UPDATE Inquiry
    SET i_subject = #{i_subject},
        i_content = #{i_content}
    WHERE i_idx = #{i_idx};

UPDATE Inquiry
    SET i_active = 1
    WHERE idx = #{i_idx};

UPDATE User_t
    SET name = #{name},
        phonenumber = #{phonenumber},
        email = #{email}
    WHERE u_idx = #{u_idx};

UPDATE Add_profile
    SET p_job = #{p_job},
        p_class = #{p_class},
        p_career = #{p_career},
        p_location = #{p_location}
    WHERE u_idx = #{u_idx};
